// Catch2's catch_user_config.hpp (regenerated by vcpkg at install time)
// unconditionally re-defines CATCH_CONFIG_CONSOLE_WIDTH to 80, which
// overrides whatever value we pass via target_compile_definitions. Force
// a wide console by including the user config first, then redefining
// the macro before any other Catch2 header (catch_test_macros.hpp pulls
// in catch_console_width.hpp which is the consumer of this value).
#include <catch2/catch_user_config.hpp>
#undef CATCH_CONFIG_CONSOLE_WIDTH
#define CATCH_CONFIG_CONSOLE_WIDTH 200

#include <catch2/catch_test_macros.hpp>
#include <catch2/catch_template_test_macros.hpp>
#include <catch2/generators/catch_generators.hpp>
#include <catch2/benchmark/catch_benchmark.hpp>
#include <libassert/assert.hpp>
#include <libassert/assert-catch2.hpp>

/** @return True after asserting that two ranges contain the same value set. */
template<
    std::ranges::contiguous_range p_range,
    typename p_value =
        std::remove_reference_t<std::ranges::range_reference_t<p_range>>
>
requires (
    std::ranges::sized_range<p_range>
)
bool assert_range_set_equality(
    const p_range& expected,
    const p_range& actual) {
    std::set<p_value> expected_set = std::ranges::to<std::set>(expected);
    std::set<p_value> actual_set = std::ranges::to<std::set>(actual);

    std::vector<p_value> els_not_present;
    std::vector<p_value> els_extra;
    std::vector<p_value> els_common;

    std::ranges::set_difference(expected_set, actual_set, std::back_inserter(els_not_present));
    std::ranges::set_difference(actual_set, expected_set, std::back_inserter(els_extra));
    std::ranges::set_intersection(actual_set, expected_set, std::back_inserter(els_common));

    const std::size_t expected_size = expected_set.size();
    const std::size_t actual_size = actual_set.size();

    std::ostringstream message;
    message
        << "assert_range_set_equality: Expect ranges to be equal (as sets). "
        << "Two sets of size (expected) " << expected_size
        << " and (actual) " << actual_size
        << " have " << els_common.size()
        << " common element, while there are " << els_not_present.size()
        << " missing and " << els_extra.size() << " extra. ";

    ASSERT(
        els_not_present.size() == 0 && els_extra.size() == 0 && els_common.size() == expected_set.size(),
        message.str(),
        els_not_present,
        els_extra,
        expected_set,
        actual_set
    );

    return true;
}

/** @return A vector containing an increasing sequence from `start`. */
template<typename p_value>
std::vector<p_value> increasing_vector(
    std::size_t length,
    p_value start = 0) {
    std::vector<p_value> v(length);
    std::iota(v.begin(), v.end(), start);
    return v;
}

/** @return A vector of fixed requested length containing increasing values. */
template<typename p_value, std::size_t p_length>
std::vector<p_value> increasing_array(p_value start = 0) {
    std::vector<p_value> v(p_length);
    std::iota(v.begin(), v.end(), start);
    return v;
}

/** @return A two-dimensional matrix filled in row-major increasing order. */
template<typename p_value>
std::vector<std::vector<p_value>> vector_increasing_matrix_2d(
    std::size_t dim_rows,
    std::size_t dim_cols,
    p_value start = 0) {
    std::vector<std::vector<p_value>> v(dim_cols);
    p_value val = start;
    for(std::size_t row_no=0;row_no<dim_rows;++row_no) {
        v[row_no].resize(dim_cols);
        for(std::size_t col_no=0;col_no<dim_cols;++col_no) {
            v[row_no][col_no] = val++;
        }
    }
    return v;
}

/** @brief Matches input ranges whose elements are themselves ranges. */
template<typename p_range>
concept nested_range =
    std::ranges::input_range<p_range> &&
    std::ranges::range<std::ranges::range_reference_t<p_range>>;

/** @brief Recursively flattens nested ranges into a joined range view. */
struct flatten_t {
    template<nested_range p_range>
    auto operator()(p_range&& range) const
    {
        return std::forward<p_range>(range) |
            std::ranges::views::transform(*this) |
            std::ranges::views::join;
    }

    template<typename p_value>
    auto operator()(p_value&& value) const
    {
        return std::forward<p_value>(value);
    }
};

/** @return The recursively flattened representation of `value`. */
template<typename p_value>
auto operator |(p_value&& value, flatten_t flatten_fn) {
    return flatten_fn(std::forward<p_value>(value));
};

/** @brief Pipeable recursive range flattener used by tests. */
constexpr flatten_t flatten;
